tool_input.command:
bun << 'EOF'
import { User } from './app/Models/User.js'
import { Post } from './app/Models/Post.js'
import app from './src/app.js'

// Bootstrap app
await app.boot()

// Create test user
const user = await User.create({
  name: 'Test User',
  email: `test-${Date.now()}@example.com`,
  password: 'test123',
})

// Create scheduled posts
const futureTime1 = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
const futureTime2 = new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString()
const pastTime = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()

await Post.forceCreate({
  title: 'Upcoming Post',
  excerpt: 'Coming soon',
  body: 'Content',
  publishedAt: futureTime1,
  authorId: user.id,
})

await Post.forceCreate({
  title: 'Later Post',
  excerpt: 'Coming later',
  body: 'Content',
  publishedAt: futureTime2,
  authorId: user.id,
})

await Post.forceCreate({
  title: 'Past Post',
  excerpt: 'Already published',
  body: 'Content',
  publishedAt: pastTime,
  authorId: user.id,
})

await Post.forceCreate({
  title: 'Published Post',
  excerpt: 'No schedule',
  body: 'Content',
  publishedAt: null,
  authorId: user.id,
})

console.log('Test data created')
process.exit(0)
EOF
